  markdown = markdown.trim();

  if (markdown.startsWith("# ") || markdown.startsWith("**" + title + "**") || markdown.startsWith("## ")) {
    // Title already inside markdown
  } else if (title && !markdown.toLowerCase().includes(title.toLowerCase())) {
    markdown = `**${title}**\n\n${markdown}`;
  }

  if (!markdown || markdown.length < 5) {
    markdown = "**Update:** Details received, but no detailed summary could be extracted.";
  }

  if (markdown.length > 1850) {
    markdown = markdown.slice(0, 1840) + "\n\n*(content truncated)*";
  }

  return {
    json: {
      ...item.json,
      title: title,
      markdown: markdown,
      finalContent: markdown
    }
  };
});

const extractItems = $("Extract URLs").all();
let scrapedItems = [];
try {
  if ($("Parse Instagram (gallery-dl)").isExecuted) {
    scrapedItems = $("Parse Instagram (gallery-dl)").all();
  }
} catch (e) {
  scrapedItems = [];
}

return $input.all().map((item, index) => {
  const text = item.json.text || item.json.response || item.json.output || "";
  let agent = "others";

  try {
    const cleanText = text.replace(/```json/g, "").replace(/```/g, "").trim();
    const parsed = JSON.parse(cleanText);
    agent = (parsed.agent || "others").toLowerCase().trim();
  } catch (e) {
    const lower = text.toLowerCase();
    if (lower.includes("project") || lower.includes("tech") || lower.includes("code") || lower.includes("software") || lower.includes("automation")) {
      agent = "project";
    } else if (lower.includes("recipe") || lower.includes("food") || lower.includes("cook") || lower.includes("bake")) {
      agent = "recipe";
    } else if (lower.includes("workout") || lower.includes("fitness") || lower.includes("gym") || lower.includes("exercise")) {
      agent = "workout";
    } else if (lower.includes("media") || lower.includes("movie") || lower.includes("film") || lower.includes("watch") || lower.includes("show")) {
      agent = "media";
    } else {
      agent = "others";
    }
  }

  if (agent.includes("project") || agent.includes("tech") || agent.includes("code")) {
    agent = "project";
  } else if (agent.includes("recipe") || agent.includes("food") || agent.includes("cook")) {
    agent = "recipe";
  } else if (agent.includes("workout") || agent.includes("fitness") || agent.includes("gym")) {
    agent = "workout";
  } else if (agent.includes("media") || agent.includes("movie") || agent.includes("watch")) {
    agent = "media";
  } else {
    agent = "others";
  }

  const origExtract = extractItems[index]?.json || extractItems[0]?.json || {};

  let scrapeData = {};
  if (scrapedItems.length > 0) {
    const match = scrapedItems.find(s => s.json.messageId && s.json.messageId === origExtract.messageId) || scrapedItems[index] || scrapedItems[0];
    if (match && match.json) {
      scrapeData = match.json;
    }
  }

  return {
    json: {
      ...origExtract,
      ...scrapeData,
      agent,
      routerOutput: text
    }
  };
});

